export const envelope = [26, 16, 28];

export default function build(api) {
  const [W, H, D] = api.size;
  const SEAT_Y = 4;

  // Safe voxel writer
  function setBlock(x, y, z, block) {
    if (x >= 0 && x < W && y >= 0 && y < H && z >= 0 && z < D) {
      api.set(x, y, z, block);
    }
  }

  // Theme palettes with robust fallbacks
  const dirtBank = api.theme.ground.bank || "minecraft:dirt";
  const dirtScree = api.theme.ground.scree || "minecraft:coarse_dirt";
  const stonePlinth = api.theme.ground.plinth || "minecraft:stone_bricks";
  const stonePrimary = api.theme.stone.primary || "minecraft:stone";
  const farmFence = api.theme.wood.fence || "minecraft:oak_fence";

  // Alien craft materials
  const HULL_IRON = "minecraft:iron_block";
  const HULL_SMOOTH = "minecraft:smooth_stone";
  const HULL_ANDESITE = "minecraft:polished_andesite";
  const HULL_OXIDIZED = "minecraft:oxidized_copper";
  const HULL_OXIDIZED_CUT = "minecraft:oxidized_cut_copper";
  const CIRCUIT_GLOW = "minecraft:sea_lantern";
  const CIRCUIT_BRICK = "minecraft:prismarine_bricks";
  const CIRCUIT_DARK = "minecraft:dark_prismarine";
  const GLASS_TINTED = "minecraft:tinted_glass";
  const GLASS_CYAN = "minecraft:cyan_stained_glass";
  const FRAME_OBSIDIAN = "minecraft:obsidian";
  const FRAME_CRYING = "minecraft:crying_obsidian";
  const SCORCH_BLACKSTONE = "minecraft:blackstone";
  const SCORCH_POLISHED = "minecraft:polished_blackstone";
  const SCORCH_BASALT = "minecraft:basalt[axis=y]";
  const SCORCH_MAGMA = "minecraft:magma_block";
  const CORE_LODESTONE = "minecraft:lodestone";
  const ROD_END = "minecraft:end_rod[facing=up]";
  const ROD_LIGHTNING = "minecraft:lightning_rod[facing=up]";
  const BARS_IRON = "minecraft:iron_bars";

  // ---------------------------------------------------------------------------
  // STEP 1: Terrain, Furrow & Crater Foundation (Ground Conformation)
  // ---------------------------------------------------------------------------
  const groundGrid = new Map();

  for (let z = 0; z < D; z++) {
    for (let x = 0; x < W; x++) {
      const gh = api.heightAt(x, z);
      const baseY = SEAT_Y + gh;

      // Skid trench geometry
      const centerlineX = 13.0 + 0.6 * Math.sin((z - 5) * 0.22);
      const distX = Math.abs(x - centerlineX);

      let furrowGouge = 0;
      let bermHeight = 0;

      if (z >= 3 && z <= 26) {
        const furrowProgress = (z - 4) / 22.0; // 0 near nose impact, 1 at furrow start
        const trenchHalfWidth = 3.2 + 2.6 * Math.sin(Math.max(0, Math.min(1, furrowProgress)) * Math.PI);

        // Impact pit at front nose (z=5..9)
        const pitDist = Math.hypot(x - 13.0, z - 7.0);
        const pitGouge = Math.max(0, 2.4 * (1.0 - pitDist / 5.2));

        // Skid furrow trailing back
        const trenchFactor = Math.max(0, 1.0 - distX / trenchHalfWidth);
        const skidGouge = 1.5 * trenchFactor * (1.0 - furrowProgress * 0.45);

        furrowGouge = Math.max(pitGouge, skidGouge);

        // Lateral spoil berms
        const bermEdgeDist = Math.abs(distX - trenchHalfWidth);
        const lateralBerm = Math.max(0, 1.8 * (1.0 - bermEdgeDist / 2.2));

        // Front impact compression wave
        const frontDist = Math.hypot(x - 13.0, z - 4.5);
        const frontBerm = Math.max(0, 2.6 * (1.0 - frontDist / 4.2));

        bermHeight = Math.max(lateralBerm, frontBerm);
      }

      const deltaY = Math.round(bermHeight - furrowGouge);
      const surfY = Math.max(1, Math.min(H - 2, Math.round(baseY + deltaY)));
      const deepY = Math.min(0, Math.round(baseY) - 2);

      groundGrid.set(`${x},${z}`, { baseY: Math.round(baseY), surfY, furrowGouge, bermHeight, deepY });

      // Fill solid foundation from lowest ground level up to modeled surface
      for (let y = deepY; y <= surfY; y++) {
        if (y < baseY - 1) {
          setBlock(x, y, z, (x + y + z) % 3 === 0 ? stonePlinth : stonePrimary);
        } else if (y < surfY) {
          setBlock(x, y, z, furrowGouge > 0.8 ? "minecraft:coarse_dirt" : dirtBank);
        } else {
          // Surface course
          if (furrowGouge > 1.2) {
            const hash = Math.sin(x * 12.9898 + z * 78.233) * 43758.5453;
            const frac = hash - Math.floor(hash);
            if (frac < 0.25) setBlock(x, y, z, SCORCH_MAGMA);
            else if (frac < 0.6) setBlock(x, y, z, SCORCH_BASALT);
            else if (frac < 0.85) setBlock(x, y, z, SCORCH_BLACKSTONE);
            else setBlock(x, y, z, "minecraft:coarse_dirt");
          } else if (furrowGouge > 0.4) {
            const hash = Math.sin(x * 5.71 + z * 9.13);
            if (hash > 0.3) setBlock(x, y, z, SCORCH_POLISHED);
            else if (hash > -0.2) setBlock(x, y, z, dirtScree);
            else setBlock(x, y, z, "minecraft:coarse_dirt");
          } else if (bermHeight > 0.8) {
            setBlock(x, y, z, dirtScree);
          } else {
            setBlock(x, y, z, dirtBank);
          }
        }
      }
    }
  }

  // Broken farm fence fragments plowed aside by the crash
  const fenceSpots = [
    [7, 21], [8, 22], [7, 24],
    [18, 20], [19, 21], [19, 23]
  ];
  for (const [fx, fz] of fenceSpots) {
    const info = groundGrid.get(`${fx},${fz}`);
    if (info) {
      setBlock(fx, info.surfY + 1, fz, farmFence);
      if ((fx + fz) % 2 === 0 && info.surfY + 2 < H) {
        setBlock(fx, info.surfY + 2, fz, farmFence);
      }
    }
  }

  // ---------------------------------------------------------------------------
  // STEP 2: Metallic Saucer Geometry (Tilted Disc Scout)
  // ---------------------------------------------------------------------------
  const cx0 = 13.0;
  const cy0 = 7.0;
  const cz0 = 13.5;

  // Forward crash tilt angle (nose embedded into -Z)
  const theta = 0.38; // ~21.8 degrees
  const cosT = Math.cos(theta);
  const sinT = Math.sin(theta);

  const R_OUTER = 8.5;

  for (let z = 3; z <= 24; z++) {
    for (let x = 4; x <= 22; x++) {
      for (let y = 1; y < H - 1; y++) {
        const dx = (x + 0.5) - cx0;
        const dy = (y + 0.5) - cy0;
        const dz = (z + 0.5) - cz0;

        // Transform into Saucer-local coordinates (u, v, w)
        const u = dx;
        const w = dz * cosT + dy * sinT;  // Longitudinal (w < 0 is nose, w > 0 is tail)
        const v = -dz * sinT + dy * cosT; // Perpendicular to saucer disc (v > 0 is top)

        const r = Math.hypot(u, w);
        if (r > R_OUTER) continue;

        const phi = Math.atan2(u, w);

        // Disc thickness profile
        let vTop = 0;
        let vBot = 0;

        if (r >= 7.0) {
          // Outer glowing rim
          const tEdge = (R_OUTER - r) / 1.5;
          vTop = 0.35 + 0.5 * tEdge;
          vBot = -0.35 - 0.5 * tEdge;
        } else if (r >= 3.4) {
          // Sloped mid-hull armor
          const tMid = (7.0 - r) / 3.6;
          vTop = 0.85 + 1.25 * Math.pow(tMid, 0.85);
          vBot = -0.85 - 0.95 * Math.pow(tMid, 0.85);
        } else {
          // Central Command Dome & Ventral Core
          const domeR = 3.4;
          const domeCap = Math.sqrt(Math.max(0, domeR * domeR - r * r));
          vTop = 1.2 + domeCap * 0.88;
          vBot = -1.1 - domeCap * 0.55;
        }

        if (v < vBot || v > vTop) continue;

        // --- Block Identification for Saucer Subsystems ---

        // 1. Crash Breach / Gash on forward port side
        const distBreach = Math.hypot((u - (-2.6)) * 1.3, (w - (-4.2)), (v - (-0.6)) * 1.5);
        if (distBreach < 1.4) {
          if (distBreach < 0.6) {
            setBlock(x, y, z, FRAME_CRYING);
          } else if (distBreach < 0.95) {
            setBlock(x, y, z, SCORCH_MAGMA);
          } else {
            setBlock(x, y, z, SCORCH_POLISHED);
          }
          continue;
        }

        // 2. Heat Scorch & Ground Abrasion (nose & underside)
        const isUnderside = v < 0;
        const isNoseImpact = w < -3.2 || (isUnderside && w < 0.0);
        if (isNoseImpact) {
          const scorchVal = Math.sin(x * 3.7 + y * 2.1 + z * 4.3);
          if (scorchVal > 0.35) {
            setBlock(x, y, z, SCORCH_POLISHED);
            continue;
          } else if (scorchVal > -0.2) {
            setBlock(x, y, z, SCORCH_BLACKSTONE);
            continue;
          } else if (scorchVal > -0.55 && isUnderside) {
            setBlock(x, y, z, SCORCH_BASALT);
            continue;
          }
        }

        // 3. Glowing Cyan Circuit Rim (7.0 <= r <= 8.5)
        if (r >= 7.0) {
          const emitterPulse = Math.sin(phi * 8);
          if (r >= 7.6) {
            if (emitterPulse > 0.35) {
              setBlock(x, y, z, CIRCUIT_GLOW);
            } else if (emitterPulse > -0.2) {
              setBlock(x, y, z, CIRCUIT_BRICK);
            } else {
              setBlock(x, y, z, HULL_OXIDIZED_CUT);
            }
          } else {
            setBlock(x, y, z, CIRCUIT_DARK);
          }
          continue;
        }

        // 4. Command Dome (r < 3.4, v >= 0.4)
        if (r < 3.4 && v >= 0.4) {
          const isCanopySurface = v >= vTop - 0.75;
          if (isCanopySurface) {
            const ribAngle = Math.abs(Math.sin(phi * 2));
            if (ribAngle < 0.22) {
              setBlock(x, y, z, FRAME_CRYING);
            } else if (r < 1.1 && v > 3.2) {
              setBlock(x, y, z, CIRCUIT_GLOW);
            } else {
              setBlock(x, y, z, (x + z) % 2 === 0 ? GLASS_CYAN : GLASS_TINTED);
            }
          } else {
            // Interior navigation core visible through glass
            if (r < 1.2 && v >= 0.6 && v <= 2.2) {
              setBlock(x, y, z, CIRCUIT_GLOW);
            } else {
              setBlock(x, y, z, CORE_LODESTONE);
            }
          }
          continue;
        }

        // 5. Ventral Propulsion Emitter (r < 3.4, v < 0)
        if (r < 3.4 && v < 0) {
          if (r < 1.2) {
            setBlock(x, y, z, CORE_LODESTONE);
          } else if (r <= 2.5 && v <= -1.2) {
            setBlock(x, y, z, CIRCUIT_GLOW);
          } else {
            setBlock(x, y, z, CIRCUIT_DARK);
          }
          continue;
        }

        // 6. Mid-Hull Armor Plates (3.4 <= r < 7.0)
        const seam = Math.abs(Math.sin(phi * 6));
        if (seam < 0.12) {
          setBlock(x, y, z, SCORCH_POLISHED); // Dark panel seam
          continue;
        }

        // Concentric secondary circuit line
        if (r >= 5.1 && r <= 5.7) {
          if (Math.sin(phi * 12) > 0.0) {
            setBlock(x, y, z, CIRCUIT_BRICK);
          } else {
            setBlock(x, y, z, HULL_OXIDIZED);
          }
          continue;
        }

        // Primary metallic alloy shell
        const plateNoise = Math.sin(u * 1.5 + w * 1.9);
        if (plateNoise > 0.3) {
          setBlock(x, y, z, HULL_IRON);
        } else if (plateNoise > -0.35) {
          setBlock(x, y, z, HULL_SMOOTH);
        } else {
          setBlock(x, y, z, HULL_ANDESITE);
        }
      }
    }
  }

  // ---------------------------------------------------------------------------
  // STEP 3: Exterior Electrostatic Rods & Breached Conduits
  // ---------------------------------------------------------------------------
  // Dome apex antenna
  const apexInfo = groundGrid.get("13,12");
  if (apexInfo) {
    setBlock(13, 12, 12, ROD_LIGHTNING);
    setBlock(13, 13, 12, ROD_END);
  }

  // Peripheral sensor nodes along raised tail rim
  setBlock(13, 11, 21, ROD_END);
  setBlock(7, 8, 17, ROD_LIGHTNING);
  setBlock(19, 8, 17, ROD_LIGHTNING);

  // Mangled internal framing hanging from the impact breach
  setBlock(10, 3, 8, BARS_IRON);
  setBlock(10, 2, 8, BARS_IRON);
  setBlock(11, 2, 7, SCORCH_MAGMA);

  return {
    name: "crashed_saucer",
    seatY: SEAT_Y,
    anchors: {
      front: [13, SEAT_Y, 0],
      impact: [13, 3, 6],
      cockpit: [13, 11, 13],
      furrow_start: [13, SEAT_Y, 26]
    }
  };
}

