export const envelope = [57, 34, 57];

export default function build(api) {
  const [W, H, D] = api.size;
  const seatY = 6;
  const cx = Math.floor(W / 2); // 28
  const cz = Math.floor(D / 2); // 28

  // 3D Voxel Grid Buffer
  const grid = new Array(W * H * D).fill(null);
  const idx = (x, y, z) => (x * H + y) * D + z;

  function setVoxel(x, y, z, block) {
    if (x >= 0 && x < W && y >= 0 && y < H && z >= 0 && z < D) {
      grid[idx(x, y, z)] = block;
    }
  }

  function getVoxel(x, y, z) {
    if (x >= 0 && x < W && y >= 0 && y < H && z >= 0 && z < D) {
      return grid[idx(x, y, z)];
    }
    return null;
  }

  // Material Palette - Biomechanical Sci-Fi Dreadnought
  const C_ARMOR = "minecraft:deepslate_tiles";
  const C_PLATING = "minecraft:polished_blackstone_bricks";
  const C_CHITIN = "minecraft:polished_deepslate";
  const C_OBSIDIAN = "minecraft:obsidian";
  const C_CRYING = "minecraft:crying_obsidian";
  const C_GLOW = "minecraft:sea_lantern";
  const C_PLASMA = "minecraft:verdant_froglight";
  const C_SCULK = "minecraft:sculk";
  const C_SCULK_CAT = "minecraft:sculk_catalyst";
  const C_GLASS = "minecraft:cyan_stained_glass";
  const C_TINTED = "minecraft:tinted_glass";
  const C_ACCENT = "minecraft:amethyst_block";
  const C_INNER = "minecraft:purpur_block";
  const C_WALL = "minecraft:deepslate_bricks";
  const C_FLOOR = "minecraft:smooth_basalt";

  // 1. MAIN SAUCER CARAPACE DISC
  for (let x = 2; x < W - 2; x++) {
    for (let z = 2; z < D - 2; z++) {
      const dx = x - cx;
      const dz = z - cz;

      // Elliptical boundary profile
      const normDist = Math.sqrt((dx / 24.5) ** 2 + ((dz + 3) / 26.5) ** 2);

      if (normDist <= 1.0) {
        const hFactor = Math.sqrt(Math.max(0, 1 - normDist ** 2));
        const yBottom = Math.round(15 - 3 * hFactor);
        const yTop = Math.round(18 + 6 * (hFactor ** 1.35));

        for (let y = yBottom; y <= yTop; y++) {
          let mat = C_CHITIN;
          if (y === yTop) {
            const angle = Math.atan2(dz, dx);
            const seam = Math.abs(Math.sin(angle * 6)) < 0.13 || Math.abs(Math.sin(normDist * 7.5)) < 0.12;
            mat = seam ? C_CRYING : (normDist > 0.82 ? C_PLATING : C_ARMOR);
          } else if (y === yBottom) {
            mat = (normDist < 0.35) ? C_CRYING : C_CHITIN;
          } else if (normDist > 0.9) {
            mat = C_OBSIDIAN;
          }
          setVoxel(x, y, z, mat);
        }
      }
    }
  }

  // 2. PREDATORY FORWARD MANDIBLES (Facing North -Z)
  for (let z = 2; z <= 24; z++) {
    const t = (24 - z) / 22; // 0 at z=24, 1 at z=2
    const mandibleR = 4.4 * (1 - 0.55 * t);
    const myCenter = 17 - 1.2 * t;

    // Left and Right Mandible Centers with menacing inward sweep
    const mxL = Math.round(cx - 10 + 2.5 * Math.sin(t * Math.PI));
    const mxR = Math.round(cx + 10 - 2.5 * Math.sin(t * Math.PI));

    const mandibles = [
      { mx: mxL, isLeft: true },
      { mx: mxR, isLeft: false }
    ];

    for (let m = 0; m < mandibles.length; m++) {
      const { mx, isLeft } = mandibles[m];
      const rCeil = Math.ceil(mandibleR);

      for (let dxM = -rCeil; dxM <= rCeil; dxM++) {
        for (let dyM = -Math.ceil(mandibleR * 0.85); dyM <= Math.ceil(mandibleR * 0.85); dyM++) {
          const dNorm = (dxM / mandibleR) ** 2 + (dyM / (mandibleR * 0.85)) ** 2;
          if (dNorm <= 1.0) {
            const px = mx + dxM;
            const py = Math.round(myCenter + dyM);
            const pz = z;

            // Glowing energy rail along the inner facing pincer surfaces
            const isInner = isLeft ? (dxM >= 0) : (dxM <= 0);
            let mat = C_ARMOR;
            if (isInner && Math.abs(dyM) <= 1) {
              mat = (pz % 3 === 0) ? C_PLASMA : C_GLOW;
            } else if (dNorm > 0.75) {
              mat = C_PLATING;
            } else if (isInner) {
              mat = C_CRYING;
            }
            setVoxel(px, py, pz, mat);
          }
        }
      }
    }
  }

  // Plasma Bombardment Focus Sphere (Suspended between Mandibles)
  for (let x = cx - 4; x <= cx + 4; x++) {
    for (let y = 14; y <= 20; y++) {
      for (let z = 9; z <= 15; z++) {
        const d = Math.sqrt((x - cx) ** 2 + (y - 17) ** 2 + (z - 12) ** 2);
        if (d <= 1.8) {
          setVoxel(x, y, z, C_PLASMA);
        } else if (d <= 2.8) {
          setVoxel(x, y, z, C_GLASS);
        } else if (d <= 3.4 && Math.abs(y - 17) <= 1) {
          setVoxel(x, y, z, C_CRYING);
        }
      }
    }
  }

  // 3. DORSAL CREST SPINE & BIOMECHANICAL RIBS
  // Central Dorsal Spine Ridge
  for (let z = 6; z <= 48; z++) {
    const tz = (z - 6) / 42;
    const spineHeight = Math.round(23 + 6.2 * Math.sin(tz * Math.PI));

    for (let y = 20; y <= spineHeight; y++) {
      for (let dxS = -2; dxS <= 2; dxS++) {
        const widthAtY = (y >= spineHeight - 1) ? 1 : 2;
        if (Math.abs(dxS) <= widthAtY) {
          let mat = C_ARMOR;
          if (dxS === 0 && y === spineHeight) {
            mat = (z % 4 === 0) ? C_GLOW : C_CRYING;
          } else if (y % 2 === 0) {
            mat = C_PLATING;
          }
          setVoxel(cx + dxS, y, z, mat);
        }
      }
    }
  }

  // Biomechanical Rib Arches
  const ribZPositions = [14, 20, 26, 32, 38];
  for (let i = 0; i < ribZPositions.length; i++) {
    const ribZ = ribZPositions[i];
    for (let side = -1; side <= 1; side += 2) {
      for (let step = 0; step <= 20; step++) {
        const s = step / 20;
        const rx = cx + side * Math.round(3 + s * 14);
        const ry = Math.round(25 + 3.8 * Math.sin(s * Math.PI) - s * 8);
        const rz = ribZ + Math.round(Math.sin(s * Math.PI) * 2.2);

        for (let tx = -1; tx <= 0; tx++) {
          for (let ty = -1; ty <= 0; ty++) {
            const mat = (tx === 0 && ty === 0 && step % 3 === 0) ? C_GLOW : (step % 2 === 0 ? C_CRYING : C_ARMOR);
            setVoxel(rx + tx, ry + ty, rz, mat);
          }
        }
      }
    }
  }

  // 4. AFT THRUSTER ENGINES
  // Central Main Engine
  for (let z = 36; z <= 53; z++) {
    const tz = (z - 36) / 17;
    const outerR = 5.0 - tz * 1.0;
    const innerR = outerR - 1.4;

    for (let dxE = -5; dxE <= 5; dxE++) {
      for (let dyE = -5; dyE <= 5; dyE++) {
        const dSq = dxE * dxE + dyE * dyE;
        if (dSq <= outerR * outerR) {
          if (dSq > innerR * innerR) {
            setVoxel(cx + dxE, 18 + dyE, z, (z >= 51) ? C_OBSIDIAN : C_ARMOR);
          } else if (z >= 45) {
            setVoxel(cx + dxE, 18 + dyE, z, (dSq <= 2.2) ? C_PLASMA : C_GLASS);
          }
        }
      }
    }
  }

  // Flanking Port and Starboard Thrusters
  const engineSides = [-14, 14];
  for (let e = 0; e < engineSides.length; e++) {
    const sideX = cx + engineSides[e];
    for (let z = 34; z <= 49; z++) {
      const tz = (z - 34) / 15;
      const outerR = 4.0 - tz * 0.8;
      const innerR = outerR - 1.3;

      for (let dxE = -4; dxE <= 4; dxE++) {
        for (let dyE = -4; dyE <= 4; dyE++) {
          const dSq = dxE * dxE + dyE * dyE;
          if (dSq <= outerR * outerR) {
            if (dSq > innerR * innerR) {
              setVoxel(sideX + dxE, 17 + dyE, z, (z >= 47) ? C_OBSIDIAN : C_ARMOR);
            } else if (z >= 42) {
              setVoxel(sideX + dxE, 17 + dyE, z, (dSq <= 1.8) ? C_GLOW : C_GLASS);
            }
          }
        }
      }
    }
  }

  // 5. VENTRAL TRACTOR EMITTER DISH & HOUSING (y = 12 to 16)
  for (let dy = 0; dy <= 4; dy++) {
    const dishY = 12 + dy;
    const dishR = 3.2 + dy * 1.2;

    for (let dx = -Math.ceil(dishR); dx <= Math.ceil(dishR); dx++) {
      for (let dz = -Math.ceil(dishR); dz <= Math.ceil(dishR); dz++) {
        const dSq = dx * dx + dz * dz;
        if (dSq <= dishR * dishR && dSq >= (dishR - 1.4) ** 2) {
          setVoxel(cx + dx, dishY, cz + dz, (dy % 2 === 0) ? C_CRYING : C_ARMOR);
        }
      }
    }
  }
  // Central Beacon Emitter Core
  for (let y = 12; y <= 15; y++) {
    setVoxel(cx, y, cz, C_GLOW);
    setVoxel(cx + 1, y, cz, C_CRYING);
    setVoxel(cx - 1, y, cz, C_CRYING);
    setVoxel(cx, y, cz + 1, C_CRYING);
    setVoxel(cx, y, cz - 1, C_CRYING);
  }

  // 6. TRACTOR BEAM, GROUND CONFORMATION & ALIEN CROP GLYPHS
  // Central Beam Column from Ground to Hull
  for (let dx = -6; dx <= 6; dx++) {
    for (let dz = -6; dz <= 6; dz++) {
      const dist = Math.sqrt(dx * dx + dz * dz);
      if (dist <= 5.2) {
        const x = cx + dx;
        const z = cz + dz;
        const gh = Math.floor(api.heightAt(x, z));
        const localGround = Math.max(0, Math.min(H - 1, seatY + gh));
        const foundationMin = Math.max(0, Math.min(seatY, localGround));

        // Foundation deep below ground
        for (let y = foundationMin; y <= localGround; y++) {
          setVoxel(x, y, z, (dist <= 2.2) ? C_SCULK_CAT : C_SCULK);
        }

        // Ascending luminous tractor beam
        for (let y = localGround + 1; y <= 12; y++) {
          if (dist <= 1.5) {
            setVoxel(x, y, z, (y % 2 === 0) ? C_GLOW : C_PLASMA);
          } else if (dist <= 3.0) {
            setVoxel(x, y, z, C_GLASS);
          } else if (dist <= 4.8) {
            const spiral = Math.sin(y * 0.75 + Math.atan2(dz, dx) * 3);
            if (spiral > 0.45) {
              setVoxel(x, y, z, C_CRYING);
            }
          }
        }
      }
    }
  }

  // Alien Crop Glyphs and Scorched Terrain Etchings
  for (let x = 3; x < W - 3; x++) {
    for (let z = 3; z < D - 3; z++) {
      const dx = x - cx;
      const dz = z - cz;
      const dist = Math.sqrt(dx * dx + dz * dz);

      if (dist >= 5.5 && dist <= 23.5) {
        const gh = Math.floor(api.heightAt(x, z));
        const localGround = Math.max(0, Math.min(H - 1, seatY + gh));
        const angle = Math.atan2(dz, dx);

        const isRing = Math.abs(dist - 9.0) < 0.85 || Math.abs(dist - 15.0) < 0.85 || Math.abs(dist - 21.0) < 0.85;
        const isRay = Math.abs(Math.sin(angle * 3)) < 0.075 && dist < 19;
        const isGlyph = Math.sin(dist * 0.75 + angle * 4) > 0.78;

        if (isRing || isRay || isGlyph) {
          const yMin = Math.max(0, Math.min(seatY, localGround));
          for (let y = yMin; y < localGround; y++) {
            setVoxel(x, y, z, C_SCULK);
          }
          let mat = C_SCULK;
          if (Math.abs(dist - 15.0) < 0.85) {
            mat = C_CRYING;
          } else if (isRay) {
            mat = C_GLOW;
          } else if (isRing) {
            mat = C_SCULK_CAT;
          }
          setVoxel(x, localGround, z, mat);
        }
      }
    }
  }

  // 7. BIOMECHANICAL GRAVITY ANCHOR LEGS (Ground Claws)
  const anchorLegs = [
    { hx: cx - 15, hy: 16, hz: cz - 10, fx: cx - 19, fz: cz - 12 },
    { hx: cx + 15, hy: 16, hz: cz - 10, fx: cx + 19, fz: cz - 12 },
    { hx: cx - 18, hy: 16, hz: cz + 2,  fx: cx - 23, fz: cz + 2  },
    { hx: cx + 18, hy: 16, hz: cz + 2,  fx: cx + 23, fz: cz + 2  },
    { hx: cx - 15, hy: 16, hz: cz + 16, fx: cx - 19, fz: cz + 20 },
    { hx: cx + 15, hy: 16, hz: cz + 16, fx: cx + 19, fz: cz + 20 }
  ];

  for (let i = 0; i < anchorLegs.length; i++) {
    const leg = anchorLegs[i];
    const fGh = Math.floor(api.heightAt(leg.fx, leg.fz));
    const fy = Math.max(0, Math.min(H - 1, seatY + fGh));

    const steps = 24;
    for (let s = 0; s <= steps; s++) {
      const t = s / steps;
      const arch = 3.2 * Math.sin(t * Math.PI);
      const tx = Math.round(leg.hx + (leg.fx - leg.hx) * t);
      const tz = Math.round(leg.hz + (leg.fz - leg.hz) * t);
      const ty = Math.round(leg.hy + (fy - leg.hy) * t + arch);

      for (let dxt = 0; dxt <= 1; dxt++) {
        for (let dzt = 0; dzt <= 1; dzt++) {
          for (let dyt = 0; dyt <= 1; dyt++) {
            const mat = (s % 4 === 0) ? C_CRYING : C_ARMOR;
            setVoxel(tx + dxt, ty + dyt, tz + dzt, mat);
          }
        }
      }
    }

    // Ground Rooting Footing
    for (let cdx = -1; cdx <= 2; cdx++) {
      for (let cdz = -1; cdz <= 2; cdz++) {
        const clawX = leg.fx + cdx;
        const clawZ = leg.fz + cdz;
        const cGh = Math.floor(api.heightAt(clawX, clawZ));
        const cLocalGround = Math.max(0, Math.min(H - 1, seatY + cGh));
        const cYmin = Math.max(0, Math.min(seatY, cLocalGround));

        for (let y = cYmin; y <= cLocalGround + 1; y++) {
          setVoxel(clawX, y, clawZ, (y === cLocalGround + 1) ? C_CRYING : C_ARMOR);
        }
      }
    }
  }

  // 8. INTERIOR ENCLOSURES & ROOM HOLLOWING
  // Interior 1: Command Bridge (y in 21..24, x in 25..31, z in 18..26)
  // Build Solid Floor, Ceiling & Walls
  for (let x = 24; x <= 32; x++) {
    for (let z = 17; z <= 27; z++) {
      setVoxel(x, 20, z, C_FLOOR);
      setVoxel(x, 25, z, C_INNER);
      for (let y = 21; y <= 24; y++) {
        if (x === 24 || x === 32 || z === 17 || z === 27) {
          let wallMat = C_WALL;
          if (z === 17) {
            wallMat = C_TINTED; // Forward viewing port
          } else if ((x === 24 || x === 32) && z === 22) {
            wallMat = C_GLOW; // Wall conduit
          }
          setVoxel(x, y, z, wallMat);
        } else {
          setVoxel(x, y, z, null); // Clear standable room volume
        }
      }
    }
  }

  // Interior 2: Central Bio-Vault / Reactor Chamber (y in 17..20, x in 24..32, z in 28..36)
  for (let x = 23; x <= 33; x++) {
    for (let z = 27; z <= 37; z++) {
      setVoxel(x, 16, z, C_FLOOR);
      setVoxel(x, 21, z, C_INNER);
      for (let y = 17; y <= 20; y++) {
        if (x === 23 || x === 33 || z === 27 || z === 37) {
          const isDoor = (x >= 27 && x <= 29) && (z === 27 || z === 37);
          if (!isDoor) {
            setVoxel(x, y, z, (x % 2 === 0) ? C_ACCENT : C_WALL);
          } else {
            setVoxel(x, y, z, null); // Connecting archway
          }
        } else {
          setVoxel(x, y, z, null); // Clear standable room volume
        }
      }
    }
  }

  // Stairway connecting Bridge (y=21) to Reactor Chamber (y=17)
  for (let x = 27; x <= 29; x++) {
    setVoxel(x, 20, 27, C_FLOOR);
    setVoxel(x, 19, 27, C_FLOOR);
    setVoxel(x, 18, 28, C_FLOOR);
    setVoxel(x, 17, 28, C_FLOOR);
    for (let y = 21; y <= 24; y++) {
      setVoxel(x, y, 27, null);
    }
  }

  // Interior 3: Aft Hangar Bay (y in 17..20, x in 25..31, z in 38..44)
  for (let x = 24; x <= 32; x++) {
    for (let z = 37; z <= 45; z++) {
      setVoxel(x, 16, z, C_FLOOR);
      setVoxel(x, 21, z, C_INNER);
      for (let y = 17; y <= 20; y++) {
        if (x === 24 || x === 32 || z === 37 || z === 45) {
          const isDoor = (x >= 27 && x <= 29) && z === 37;
          if (!isDoor) {
            setVoxel(x, y, z, C_WALL);
          } else {
            setVoxel(x, y, z, null); // Connecting doorway
          }
        } else {
          setVoxel(x, y, z, null); // Clear standable room volume
        }
      }
    }
  }

  // 9. EMIT VOXELS TO WORLD
  for (let x = 0; x < W; x++) {
    for (let y = 0; y < H; y++) {
      for (let z = 0; z < D; z++) {
        const block = grid[idx(x, y, z)];
        if (block !== null) {
          api.set(x, y, z, block);
        }
      }
    }
  }

  return {
    name: "Alien Mothership Dreadnought",
    seatY: seatY,
    anchors: {
      front: [cx, 18, 0] // North-facing prow anchor (-Z)
    },
    interiors: [
      { min: [25, 21, 18], max: [31, 24, 26], kind: "bridge" },
      { min: [24, 17, 28], max: [32, 20, 36], kind: "vault" },
      { min: [25, 17, 38], max: [31, 20, 44], kind: "hall" }
    ]
  };
}

